    <script>
        // Data siswa dummy, bisa diganti dengan hasil fetch backend
        const siswaData = [
            {
                nama: "Lucian",
                jurusan: "TKJ",
                bulan: "Maret",
                tahun: "2025",
                hadir: 26,
                tidakHadir: 5,
