                    { tanggal: "07-03-2025", keterangan: "Terlambat" },
                    { tanggal: "17-03-2025", keterangan: "Terlambat" }
                ]
            },
            {
                nama: "Rina",
                jurusan: "RPL",
                bulan: "Maret",
                tahun: "2025",
                hadir: 28,
                tidakHadir: 0,
                izinSakit: 1,
                terlambat: 0,
                detail: [
                    { tanggal: "03-03-2025", keterangan: "Sakit" }
                ]
            },
            {
                nama: "Budi",
                jurusan: "TKJ",
                bulan: "Februari",
                tahun: "2025",
                hadir: 23,
                tidakHadir: 2,
                izinSakit: 0,
                terlambat: 0,
                detail: [
                    { tanggal: "10-02-2025", keterangan: "Tidak Hadir" },
                    { tanggal: "11-02-2025", keterangan: "Tidak Hadir" }
                ]
            },
            {
                nama: "Ani",
                jurusan: "AKL",
                bulan: "Maret",
                tahun: "2025",
                hadir: 25,
                tidakHadir: 3,
                izinSakit: 2,
                terlambat: 1,
                detail: [
                    { tanggal: "05-03-2025", keterangan: "Tidak Hadir" },
                    { tanggal: "12-03-2025", keterangan: "Tidak Hadir" },
                    { tanggal: "19-03-2025", keterangan: "Tidak Hadir" },
                    { tanggal: "08-03-2025", keterangan: "Izin" },
                    { tanggal: "14-03-2025", keterangan: "Sakit" },
                    { tanggal: "09-03-2025", keterangan: "Terlambat" }
                ]
            }
        ];

        // State untuk filter
        let selectedJurusan = 'all';
        let selectedBulan = 'all';
        let selectedTahun = 'all';

        // Render function
        function renderAttendanceList() {
            const list = document.getElementById("attendanceList");
            list.innerHTML = '';

            // Filter data
            const filtered = siswaData.filter(s =>
                (selectedJurusan === 'all' || s.jurusan === selectedJurusan) &&
                (selectedBulan === 'all' || s.bulan === selectedBulan) &&
                (selectedTahun === 'all' || s.tahun === selectedTahun)
            );

            if(filtered.length === 0) {
                list.innerHTML = `<div class="alert alert-warning">Data tidak ditemukan.</div>`;
                return;
            }

            filtered.forEach(s => {
                // Group detail kiri-kanan (2 kolom)
                let detailKiri = "", detailKanan = "";
                s.detail.forEach((d, i) => {
                    const html = `<p>${d.tanggal} : ${d.keterangan}</p>`;
                    if(i % 2 === 0) detailKiri += html;
                    else detailKanan += html;
                });

                list.innerHTML += `
                <div class="attendance-card card p-3 mb-3" onclick="toggleDetails(this)">
                    <div class="d-flex justify-content-between align-items-center">
                        <h5>${s.nama} - ${s.jurusan}</h5>
                        <i class="bi bi-chevron-down"></i>
                    </div>
                    <div class="attendance-summary">
                        <p><strong>Hadir:</strong> ${s.hadir} hari</p>
                        <p><strong>Tidak Hadir:</strong> ${s.tidakHadir} hari</p>
                        <p><strong>Izin/Sakit:</strong> ${s.izinSakit} hari</p>
                        <p><strong>Terlambat:</strong> ${s.terlambat} hari</p>
                    </div>
                    <div class="details" style="display: none;">
                        <p class="fw-bold">Detail Ketidakhadiran:</p>
                        <div class="row">
                            <div class="col-md-6">${detailKiri}</div>
                            <div class="col-md-6">${detailKanan}</div>
                        </div>
                    </div>
                </div>`;
            });
        }

        // Handle dropdown selection
        function setupDropdown(dropdownId, btnId, property) {
            document.querySelectorAll(`#${dropdownId} .dropdown-item`).forEach(item => {
                item.addEventListener('click', function(e) {
                    e.preventDefault();
                    const value = this.getAttribute('data-value');
                    const text = this.textContent;

                    // Update selected value
                    if (property === 'jurusan') selectedJurusan = value;
                    else if (property === 'bulan') selectedBulan = value;
                    else if (property === 'tahun') selectedTahun = value;

                    // Update button text
                    document.getElementById(btnId).textContent = text;

                    // Re-render the list
                    renderAttendanceList();
                });
            });
        }

        // Initialize when DOM is loaded
        document.addEventListener("DOMContentLoaded", function() {
            // Setup dropdowns
            setupDropdown("jurusanDropdown", "jurusanDropdownBtn", "jurusan");
            setupDropdown("bulanDropdown", "bulanDropdownBtn", "bulan");
            setupDropdown("tahunDropdown", "tahunDropdownBtn", "tahun");

            // Initial render
            renderAttendanceList();
        });

        // Toggle details
        function toggleDetails(element) {
            const details = element.querySelector('.details');
            const chevron = element.querySelector('.bi-chevron-down, .bi-chevron-up');

            if (details.style.display === 'none' || details.style.display === '') {
                details.style.display = 'block';
                chevron.classList.remove('bi-chevron-down');
                chevron.classList.add('bi-chevron-up');
            } else {
                details.style.display = 'none';
                chevron.classList.remove('bi-chevron-up');
                chevron.classList.add('bi-chevron-down');
            }
        }
    </script>

