        <script>
            $(document).ready(function() {
                $('#filterForm').on('submit', function(e) {
                    e.preventDefault();

                    let bulan = $('#bulan').val();
                    let tahun = $('#tahun').val();

                    $.ajax({
                        url: '{{ route('ringkasanabsenpt.filter') }}',
                        method: 'GET',
                        data: {
                            bulan: bulan,
