                        },
                        beforeSend: function() {
                            $('#absensiBody').html('<tr><td colspan="6">Memuat data...</td></tr>');
                        },
                        success: function(response) {
                            $('#absensiBody').html(response.html);
                        },
                        error: function(xhr) {
                            $('#absensiBody').html(
                                '<tr><td colspan="6">Terjadi kesalahan.</td></tr>');
                            console.error(xhr.responseText);
                        }
                    });
                });
            });
